package main

import "embed"

// distFS holds the built frontend. It has to live next to web/ because
// go-embed cannot reach outside the directory of the file that declares it,
// which is also why the server takes an fs.FS instead of embedding assets
// itself.
//
// web/dist is generated by `npm run build` and is not committed: only the
// empty web/dist/.gitkeep is. The `all:` prefix makes the pattern include dot
// files, so that placeholder alone keeps this directive valid on a fresh
// clone — `go build` compiles, and the server reports the missing assets only
// when it actually starts. Build the frontend first (`make build`) for a
// runnable binary.
//
//go:embed all:web/dist
var distFS embed.FS
